<script setup>
import {ref,reactive} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api} from '../lib/api.js'
import {session,signIn} from '../lib/session.js'
import AppIcon from '../components/AppIcon.vue'
const router=useRouter(),route=useRoute(),mode=ref('login'),formRef=ref(),busy=ref(false),error=ref('')
const form=reactive({username:'',password:'',displayName:''})
const rules={username:[{required:true,message:'请输入用户名',trigger:'blur'},{pattern:/^[A-Za-z0-9_]{3,32}$/,message:'用户名为3至32位字母、数字或下划线',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:8,max:64,message:'密码长度为8至64位',trigger:'blur'},{pattern:/^[\x21-\x7E]+$/,message:'密码请使用英文、数字或符号，不含空格',trigger:'blur'}],displayName:[{required:true,message:'请输入显示名称',trigger:'blur'},{max:40,message:'名称最多40字',trigger:'blur'}]}
function switchMode(value){mode.value=value;error.value='';formRef.value?.clearValidate()}
async function submit(){if(busy.value)return;if(!await formRef.value.validate().catch(()=>false))return;busy.value=true;error.value='';try{if(mode.value==='register'){await api.post('/auth/register',form);ElMessage.success('注册成功，欢迎使用酱味账本')}await signIn(form.username,form.password);const target=route.query.redirect;await router.replace(typeof target==='string'&&target.startsWith('/')&&!target.startsWith('//')?target:'/')}catch(e){error.value=e.message}finally{busy.value=false}}
</script><template><div class="auth-page"><section class="auth-story"><div class="brand"><span class="brand-icon"><AppIcon name="Notebook" :size="25"/></span><span>酱味账本<small>JIANGWEI LEDGER</small></span></div><div class="auth-story-body"><span class="eyebrow">给生活，留一本账</span><h1>从一笔记录开始，<br>看见你的日常。</h1><p>记下收支，安排预算。<br>让每个月的消费，都清清楚楚。</p><div class="ledger-art" aria-hidden="true"><div class="art-circle"></div><div class="art-book"><span>我的生活账本</span><i></i><i></i><i></i><b>收支 · 预算 · 分析</b></div><span class="art-stamp"><AppIcon name="Check" :size="30"/></span></div></div><small class="auth-credit">酱味大鸡 · 课程项目</small></section><section class="auth-form-area"><div class="auth-card"><span class="eyebrow">WELCOME TO YOUR LEDGER</span><h2>{{mode==='login'?'欢迎回来':'创建你的账本'}}</h2><p class="muted">{{mode==='login'?'登录后，继续记录今天的生活。':'只需一个账号，开始管理日常收支。'}}</p><div class="auth-tabs" role="tablist" aria-label="账户操作"><button role="tab" :aria-selected="mode==='login'" :class="{selected:mode==='login'}" @click="switchMode('login')">登录</button><button role="tab" :aria-selected="mode==='register'" :class="{selected:mode==='register'}" @click="switchMode('register')">注册</button></div><el-alert v-if="session.expired" title="登录已失效，请重新登录" type="warning" :closable="false" class="mb"/><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top" size="large" @submit.prevent="submit"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" autocomplete="username" placeholder="3至32位字母、数字或下划线" maxlength="32"/></el-form-item><el-form-item v-if="mode==='register'" label="显示名称" prop="displayName"><el-input v-model="form.displayName" placeholder="在账本里如何称呼你" maxlength="40"/></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password :autocomplete="mode==='login'?'current-password':'new-password'" placeholder="8至64位英文、数字或符号" maxlength="64"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy" class="auth-submit">{{mode==='login'?'登录账本':'注册并登录'}}<AppIcon name="Right" :size="17"/></el-button></el-form><div class="auth-hint"><AppIcon name="Lock" :size="14"/>账户之间的账单独立保存</div></div></section></div></template>
